    /// <summary>
    /// Creates a collection from gifts on the current user's or a channel's profile page; requires can_post_messages administrator right in the channel chat.
    /// An owner can have up to getOption("gift_collection_count_max") gift collections. The new collection will be added to the end of the gift collection list of the owner. Returns the created collection
    /// </summary>
    public Task<TdLib.TdApi.Objects.GiftCollection> CreateGiftCollectionAsync(MessageSender ownerId = default, string name = default, string[] receivedGiftIds = default)
    {

           using var activity =  StartCallActivity("CreateGiftCollectionAsync", typeof(CreateGiftCollection).FullName ?? "CreateGiftCollectionAsync");

           try
           {
             return client.CreateGiftCollectionAsync(ownerId, name, receivedGiftIds);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
